{
  "name": "多道分析器（MCA）",
  "name_en": "Multichannel Analyzer (MCA)",
  "manufacturer": "",
  "description": "多道分析器是一种用于辐射探测信号能谱测量的电子仪器，可将探测器输出的脉冲按幅度分箱并形成能谱。它常用于 X 射线或伽马射线谱测量、峰分析、感兴趣区域计数以及同步辐射和核探测实验中的能量分辨检测。",
  "description_en": "A multichannel analyzer is an electronic instrument used for energy-spectrum measurements of radiation detector signals. It sorts detector pulses by amplitude into channels to build a spectrum, and is commonly used for X-ray or gamma-ray spectroscopy, peak analysis, region-of-interest counting, and energy-resolved detection in synchrotron and nuclear experiments.",
  "actions": [
    {
      "action_name": "auto-stop",
      "description": "停止当前采集或计数。",
      "description_en": "Stop the current acquisition or counting process."
    },
    {
      "action_name": "auto-get_low_level_parameter",
      "description": "获取底层脉冲处理或采集参数。",
      "description_en": "Get a low-level pulse-processing or acquisition parameter."
    },
    {
      "action_name": "auto-stage",
      "description": "按预设计数模式和采集设置准备设备进入测量状态。",
      "description_en": "Prepare the device for measurement using the configured preset mode and acquisition settings."
    }
  ],
  "tag_hints": [
    "multichannel analyzer",
    "pulse-height spectrum",
    "X-ray spectroscopy",
    "gamma spectroscopy",
    "ROI counting",
    "detector readout",
    "energy-resolved detection"
  ]
}

